Repair the CommonJS source below. It must export exactly `{ markKeywords }`. `markKeywords(text, keywords)` requires a string and an array of nonempty strings; malformed inputs throw `TypeError`. Keyword matching is case-insensitive while output preserves the original text. Duplicate keywords under case-insensitive comparison are ignored after their first occurrence. Scan from left to right without overlaps. If multiple keywords begin at the same position, choose the longest; equal-length ties use the earliest keyword. Return segments shaped as `{ text, matched }`, preserving all input characters. Consecutive unmatched characters must share one segment, while each match is its own segment. Empty text returns `[]`; text without matches returns one unmatched segment. Do not mutate inputs. Return a corrected complete source file.

```javascript
function markKeywords(text, keywords) {
  if (typeof text !== 'string' || !Array.isArray(keywords)) {
    throw new TypeError('invalid arguments');
  }
  if (keywords.some(keyword => typeof keyword !== 'string' || keyword === '')) {
    throw new TypeError('keywords must be nonempty strings');
  }

  const seen = new Set();
  const ordered = [];
  keywords.forEach((keyword, index) => {
    const lower = keyword.toLowerCase();
    if (!seen.has(lower)) {
      seen.add(lower);
      ordered.push({ lower, index });
    }
  });
  ordered.sort((a, b) => a.lower.length - b.lower.length || a.index - b.index);

  const lowerText = text.toLowerCase();
  const result = [];
  let plain = '';
  let position = 0;

  while (position < text.length) {
    const match = ordered.find(entry => lowerText.startsWith(entry.lower, position));
    if (!match) {
      plain += text[position];
      position += 1;
      continue;
    }
    if (plain !== '') {
      result.push({ text: plain, matched: false });
      plain = '';
    }
    result.push({ text: text.slice(position, position + match.lower.length), matched: true });
    position += match.lower.length;
  }

  if (plain !== '') result.push({ text: plain, matched: false });
  return result;
}

module.exports = { markKeywords };
```

