'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api).sort(), ['markKeywords']);
const { markKeywords } = api;

assert.throws(() => markKeywords(null, []), TypeError);
assert.throws(() => markKeywords('text', null), TypeError);
assert.throws(() => markKeywords('text', 'text'), TypeError);
for (const keywords of [[''], ['ok', ''], [1], [null], [{}]]) {
  assert.throws(() => markKeywords('text', keywords), TypeError);
}

assert.deepEqual(markKeywords('', []), []);
assert.deepEqual(markKeywords('', ['anything']), []);
assert.deepEqual(markKeywords('No matches here', []), [
  { text: 'No matches here', matched: false }
]);
assert.deepEqual(markKeywords('No matches here', ['xyz']), [
  { text: 'No matches here', matched: false }
]);

assert.deepEqual(markKeywords('Say JavaScript, then JAVA.', ['java', 'javascript']), [
  { text: 'Say ', matched: false },
  { text: 'JavaScript', matched: true },
  { text: ', then ', matched: false },
  { text: 'JAVA', matched: true },
  { text: '.', matched: false }
]);
assert.deepEqual(markKeywords('catalog', ['cat', 'catalog', 'log']), [
  { text: 'catalog', matched: true }
]);
assert.deepEqual(markKeywords('ababa', ['aba', 'ab']), [
  { text: 'aba', matched: true },
  { text: 'ba', matched: false }
]);
assert.deepEqual(markKeywords('xxABCyyabc', ['abc', 'ABC', 'ab']), [
  { text: 'xx', matched: false },
  { text: 'ABC', matched: true },
  { text: 'yy', matched: false },
  { text: 'abc', matched: true }
]);
assert.deepEqual(markKeywords('one two', ['one', 'two']), [
  { text: 'one', matched: true },
  { text: ' ', matched: false },
  { text: 'two', matched: true }
]);
assert.deepEqual(markKeywords('aaaa', ['aa']), [
  { text: 'aa', matched: true },
  { text: 'aa', matched: true }
]);
assert.deepEqual(markKeywords('xabc', ['bc', 'abc']), [
  { text: 'x', matched: false },
  { text: 'abc', matched: true }
]);

const keywords = ['Alpha', 'BETA'];
const copy = keywords.slice();
const text = 'alpha beta';
const segments = markKeywords(text, keywords);
assert.deepEqual(keywords, copy);
assert.equal(text, 'alpha beta');
segments[0].text = 'changed';
assert.deepEqual(markKeywords(text, keywords), [
  { text: 'alpha', matched: true },
  { text: ' ', matched: false },
  { text: 'beta', matched: true }
]);

